    legend = 'spike only: L = 0 outside ≈' + (span * 180 / Math.PI).toFixed(1) + '° of directions';
  }
  gCard.circle(4).center(cx, cy).fill('#888');

  txt(gCard, 'L(x, y, θ) — radiance vs. direction', cx, 17, 8.5, '#222', 'center');
  txt(gCard, '0°', cx + R + 11, cy, 6.5, '#777', 'center');
  txt(gCard, '90°', cx, cy - R - 9, 6.5, '#777', 'center');
  txt(gCard, '180°', cx - R - 13, cy, 6.5, '#777', 'center');
  txt(gCard, '270°', cx, cy + R + 10, 6.5, '#777', 'center');
  txt(gCard, legend, CARD.x + 7, 133, 7, '#555');
  txt(gCard, 'radius = radiance · colour = surface seen', CARD.x + 7, 142, 7, '#8a8f95');

  gCard.rect(CARD.w, CARD.h).move(CARD.x, CARD.y).fill('#fff').opacity(0.01).css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Angular distribution of light at the probe: radius = radiance, colour = what that direction sees.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function (e) {
