}

/* ── ray-trace animation ────────────────────────────────────────── */
function polyLen(pts) {
  var L = 0; for (var i = 1; i < pts.length; i++) L += Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
  return L;
}
function pointAt(pts, d) {
  for (var i = 1; i < pts.length; i++) {
    var seg = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    if (d <= seg) { var f = seg ? d / seg : 0; return [pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * f, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * f]; }
    d -= seg;
  }
  return pts[pts.length - 1];
}
function rebuildAnim() {
