      var h = castRay(p.x, p.y, dx, dy, false);
      if (h.I < 0.02) continue;
      var rr = Math.max(30, Math.min(78, h.t));
      animPaths.push({ pts: [[p.x + dx * rr, p.y + dy * rr], [p.x + dx * 15, p.y + dy * 15]], color: h.color });
    }
  } else {
    var targets = [p];
    if (Math.abs(p.x - DOT_TOP.x) < 2 && Math.abs(p.y - DOT_TOP.y) < 2) targets.push(DOT_BOT);
    else if (Math.abs(p.x - DOT_BOT.x) < 2 && Math.abs(p.y - DOT_BOT.y) < 2) targets.push(DOT_TOP);
    for (var q = 0; q < targets.length; q++) {
      var tp = targets[q], hh = castRay(tp.x, tp.y, BOX.x2 - tp.x, PIN_Y - tp.y, true);
      if (hh.I < 0.02) continue;
      animPaths.push({ pts: [[hh.x, hh.y], [BOX.x2, PIN_Y], [tp.x, tp.y]], color: hh.color });
    }
  }
  for (var k = 0; k < animPaths.length; k++) {
    animPaths[k].len = polyLen(animPaths[k].pts);
    for (var s = 0; s < 2; s++) {
      photons.push({
        path: animPaths[k],
        off: (k * 0.37 + s * 0.5) % 1,
        node: gAnim.circle(6).fill(animPaths[k].color).stroke({ color: '#000', width: 0.6 })
      });
    }
  }
}
function setAnim(on) {
