    var ph = (ts / 1200) % 1;
    pulseRing.radius(13 + 11 * ph).stroke({ color: RED, width: 1.6, opacity: 0.65 * (1 - ph) });
  }
  if (animOn) {
    for (var i = 0; i < photons.length; i++) {
      var ph2 = photons[i], f = ((ts * 0.00042) + ph2.off) % 1;
      var pt = pointAt(ph2.path.pts, f * ph2.path.len);
      ph2.node.center(pt[0], pt[1]).opacity(f < 0.06 ? f / 0.06 : (f > 0.94 ? (1 - f) / 0.06 : 1));
    }
  }
  requestAnimationFrame(frame);
}

/* ── render / interaction ───────────────────────────────────────── */
function render() {
